from pathlib import Path

p = Path("src/pages/admin/AdminPage.tsx")
s = p.read_text(encoding="utf-8")


def once(old: str, new: str, label: str) -> None:
    global s
    if old not in s:
        raise RuntimeError(f"Missing patch target: {label}")
    s = s.replace(old, new, 1)


